import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.DYd_c05j.js";const u=JSON.parse('{"title":"MCP Lite Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"benchmark.md","filePath":"benchmark.md","lastUpdated":null}'),l={name:"benchmark.md"};function i(n,t,s,d,h,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="mcp-lite-benchmark" tabindex="-1">MCP Lite Benchmark <a class="header-anchor" href="#mcp-lite-benchmark" aria-label="Permalink to &quot;MCP Lite Benchmark&quot;">​</a></h1><p>The MCP Lite benchmark tests the central product claim behind Homelab Console: a smaller model can be fast and accurate when the control plane first reduces the problem to compact observations and a narrow tool surface.</p><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Method&quot;">​</a></h2><p>Each model received the same prompt and the same reduced MCP catalog of 12 read-only tools. Each result below is a single execution per test, not an average over repeated runs. The three routes were:</p><ul><li><strong>General</strong> — overall homelab summary;</li><li><strong>Network</strong> — normalized network summary;</li><li><strong>Uptime Kuma</strong> — monitor status summary.</li></ul><p>Latency includes the complete model turn used to select the route and produce the response. The benchmark records tool selection, expected call count, and observable output issues.</p><div class="warning custom-block"><p class="custom-block-title">EARLY DIRECTIONAL RESULT</p><p>One execution per test is enough to compare this controlled run, but not enough to establish statistical variance. Treat the ranking as directional and re-run it after model, prompt, hardware, network, or tool-catalog changes.</p></div><h2 id="latency" tabindex="-1">Latency <a class="header-anchor" href="#latency" aria-label="Permalink to &quot;Latency&quot;">​</a></h2><p>All times are seconds. Lower is better.</p><table tabindex="0"><thead><tr><th>Model</th><th style="text-align:right;">General</th><th style="text-align:right;">Network</th><th style="text-align:right;">Uptime Kuma</th><th style="text-align:right;">Mean</th></tr></thead><tbody><tr><td><strong>Qwen 3.5 4B local</strong></td><td style="text-align:right;"><strong>16.8</strong></td><td style="text-align:right;"><strong>10.9</strong></td><td style="text-align:right;"><strong>8.0</strong></td><td style="text-align:right;"><strong>11.9</strong></td></tr><tr><td>DeepSeek V4 Flash</td><td style="text-align:right;">21.3</td><td style="text-align:right;">12.2</td><td style="text-align:right;">8.4</td><td style="text-align:right;">14.0</td></tr><tr><td>DeepSeek V4 Pro</td><td style="text-align:right;">28.2</td><td style="text-align:right;">12.8</td><td style="text-align:right;">11.0</td><td style="text-align:right;">17.3</td></tr><tr><td>GPT-5.6 Luna Fast</td><td style="text-align:right;">31.3</td><td style="text-align:right;">18.2</td><td style="text-align:right;">19.2</td><td style="text-align:right;">22.9</td></tr><tr><td>GPT-5.6 Sol</td><td style="text-align:right;">36.3</td><td style="text-align:right;">31.9</td><td style="text-align:right;">21.2</td><td style="text-align:right;">29.8</td></tr></tbody></table><p>Qwen was fastest in all three routes. Based on the displayed means, it was about 15% faster than DeepSeek Flash, 31% faster than DeepSeek Pro, 48% faster than Luna Fast, and 60% faster than Sol.</p><h2 id="tool-accuracy" tabindex="-1">Tool accuracy <a class="header-anchor" href="#tool-accuracy" aria-label="Permalink to &quot;Tool accuracy&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th style="text-align:right;">Correct tools</th><th style="text-align:right;">Expected calls</th><th>Observed issues</th></tr></thead><tbody><tr><td>Qwen 3.5 4B local</td><td style="text-align:right;">3/3</td><td style="text-align:right;">3/3</td><td>No substantive issue</td></tr><tr><td>DeepSeek V4 Flash</td><td style="text-align:right;">3/3</td><td style="text-align:right;">3/3</td><td>Translated the next action and added healthy details</td></tr><tr><td>DeepSeek V4 Pro</td><td style="text-align:right;">3/3</td><td style="text-align:right;">3/3</td><td>None</td></tr><tr><td>GPT-5.6 Luna Fast</td><td style="text-align:right;">3/3</td><td style="text-align:right;">3/3</td><td>None</td></tr><tr><td>GPT-5.6 Sol</td><td style="text-align:right;">3/3</td><td style="text-align:right;">3/3</td><td>None</td></tr></tbody></table><p>Every model selected the correct tool and made the expected number of calls. The difference in this run was therefore latency and output discipline, not basic route accuracy.</p><h2 id="recommended-fit" tabindex="-1">Recommended fit <a class="header-anchor" href="#recommended-fit" aria-label="Permalink to &quot;Recommended fit&quot;">​</a></h2><ol><li><strong>Qwen 3.5 4B local</strong> — best combination of speed, privacy, and accuracy on this workload.</li><li><strong>DeepSeek V4 Pro</strong> — best balanced commercial alternative when output discipline matters more than minimum latency.</li><li><strong>GPT-5.6 Luna Fast</strong> — reliable, but materially slower for simple summary routing.</li><li><strong>GPT-5.6 Sol</strong> — accurate, but oversized for these deterministic summary questions.</li><li><strong>DeepSeek V4 Flash</strong> — fast, but less strict about preserving the requested response format in this run.</li></ol><h2 id="what-this-proves-—-and-what-it-does-not" tabindex="-1">What this proves — and what it does not <a class="header-anchor" href="#what-this-proves-—-and-what-it-does-not" aria-label="Permalink to &quot;What this proves — and what it does not&quot;">​</a></h2><p>The result supports using a local 4B model for MCP Lite read-only questions when Homelab Console supplies deterministic summaries and routes among 12 tools. It does not show that the same model is ready for:</p><ul><li>ambiguous incident diagnosis;</li><li>multi-provider causal correlation;</li><li>long-horizon investigation;</li><li>remediation planning;</li><li>infrastructure writes.</li></ul><p>Commercial models are still likely to be stronger on those workloads. They need a separate benchmark with repeated runs, explicit quality criteria, and operator-reviewed safety evidence. No model should receive write authority: all infrastructure writes remain typed, input-bound, audited, and approved by the operator per invocation.</p><p>Continue with <a href="./local-models">Local Models</a> for the selection guide or the <a href="./mcp">MCP adapter</a> for the governed tool contract.</p>',21)])])}const m=e(l,[["render",i]]);export{u as __pageData,m as default};
